# ==== leaflet_loading_helpers.r =============================================
##
## PURPOSE:
##   Add a BRIM startup loading overlay with an animated hydrology backdrop so
##   users can clearly see that the page is still loading.
##
## PATCH 32h:
##   Fresh implementation. Uses the user's preferred landscape image as the
##   loading backdrop and adds a CSS-only SVG dotted-flow overlay. This avoids
##   the prior JS particle loop and removes the large translucent shape / guide
##   polygons that were visually distracting.
##
## NOTE:
##   Internal function names retain the existing pt_* convention so the helper
##   stays compatible with the current map builder. User-facing branding is
##   BRIM.
## ============================================================================

`%||%` <- function(x, y) {
  if (is.null(x) || length(x) == 0 || is.na(x[1])) y else x
}

pt_startup_loading_brand_message <- function(x) {
  x <- as.character(x %||% "")
  x <- gsub("PortaTreasure2", "BRIM", x, fixed = TRUE)
  x <- gsub("PT2", "BRIM", x, fixed = TRUE)
  x
}

pt_add_startup_loading_overlay <- function(m) {

  brim_loader_bg_uri <- "data:image/jpeg;base64,"

  if (!requireNamespace("base64enc", quietly = TRUE)) {
    stop("Package 'base64enc' is required to embed loading-page branding.")
  }

  embed_loading_asset <- function(
    path,
    expected_extension,
    mime_type,
    header_pattern,
    header_bytes,
    label
  ) {
    asset_info <- file.info(path)
    if (
      !file.exists(path) ||
      is.na(asset_info$size) ||
      asset_info$size <= 0 ||
      tolower(tools::file_ext(path)) != expected_extension
    ) {
      stop("Missing or invalid approved ", label, ": ", path)
    }

    asset_bytes <- readBin(
      path,
      what = "raw",
      n = as.integer(asset_info$size)
    )
    asset_header <- rawToChar(
      asset_bytes[seq_len(min(length(asset_bytes), header_bytes))]
    )
    if (!grepl(header_pattern, asset_header, ignore.case = TRUE)) {
      stop("Approved ", label, " has an invalid file signature.")
    }

    paste0(
      "data:",
      mime_type,
      ";base64,",
      base64enc::base64encode(asset_bytes)
    )
  }

  topo_background_uri <- embed_loading_asset(
    path = file.path("00_config", "Topo3whiteReversed.svg"),
    expected_extension = "svg",
    mime_type = "image/svg+xml",
    header_pattern = "<svg[[:space:]>]",
    header_bytes = 2048L,
    label = "loading-page topo background"
  )
  doi_seal_uri <- embed_loading_asset(
    path = file.path("00_config", "doicolor.gif"),
    expected_extension = "gif",
    mime_type = "image/gif",
    header_pattern = "^GIF8[79]a",
    header_bytes = 6L,
    label = "DOI loading seal"
  )
  blm_emblem_uri <- embed_loading_asset(
    path = file.path("00_config", "blmlogo.svg"),
    expected_extension = "svg",
    mime_type = "image/svg+xml",
    header_pattern = "<svg[[:space:]>]",
    header_bytes = 2048L,
    label = "BLM loading emblem"
  )

  loading_markup <- htmltools::tagList(
    htmltools::tags$style(
      htmltools::HTML(r"---(
        #brim-startup-loading-overlay {
          position: fixed;
          inset: 0;
          z-index: 2147483000;
          min-height: 100vh;
          min-height: 100dvh;
          display: flex;
          align-items: center;
          justify-content: center;
          background:
            radial-gradient(circle at 18% 16%, rgba(65, 116, 127, 0.22), transparent 36%),
            radial-gradient(circle at 82% 8%, rgba(44, 87, 96, 0.18), transparent 30%),
            linear-gradient(135deg, #132126, #1a2d32 54%, #0e191d);
          color: #172a2d;
          font-family: Inter, "Segoe UI", Roboto, Arial, Helvetica, sans-serif;
          opacity: 1;
          transition: opacity 0.42s ease;
          pointer-events: auto;
          overflow: auto;
          padding: 12px;
          box-sizing: border-box;
        }

        #brim-startup-loading-overlay::before {
          content: '';
          position: absolute;
          inset: 0;
          background-image: var(--brim-topo-background);
          background-position: center center;
          background-size: cover;
          background-repeat: no-repeat;
          opacity: 0.24;
          pointer-events: none;
        }

        #brim-startup-loading-overlay.brim-startup-loading-hidden {
          opacity: 0;
          pointer-events: none;
        }

        .brim-startup-card {
          --brim-headline-font: "Franklin Gothic Condensed", "Franklin Gothic Medium Cond", "Arial Narrow", "Aptos Narrow", "Helvetica Neue", Arial, sans-serif;
          --brim-body-font: Garamond, "Adobe Garamond Pro", "EB Garamond", Georgia, serif;
          width: min(980px, calc(100vw - 42px));
          height: 960px;
          height: min(960px, calc(100vh - 24px));
          height: min(960px, calc(100dvh - 24px));
          max-height: calc(100vh - 24px);
          max-height: calc(100dvh - 24px);
          display: grid;
          grid-template-rows: auto minmax(0, 1fr) auto;
          border: 1px solid rgba(19, 63, 72, 0.18);
          border-radius: 22px;
          background: #ffffff;
          box-shadow:
            0 24px 64px rgba(18, 48, 54, 0.22),
            0 0 0 1px rgba(255,255,255,0.72) inset;
          padding: 26px 28px 22px 28px;
          box-sizing: border-box;
          overflow: hidden;
          position: relative;
          z-index: 1;
          flex: 0 0 auto;
          margin: auto;
        }

        .brim-startup-card::before {
          content: '';
          position: absolute;
          inset: -56px -96px auto auto;
          width: 280px;
          height: 280px;
          border-radius: 50%;
          background: radial-gradient(circle, rgba(47,142,163,0.12), transparent 66%);
          pointer-events: none;
        }

        .brim-startup-heading {
          min-width: 0;
        }

        .brim-startup-kicker {
          margin: 0 0 6px 0;
          font-family: var(--brim-headline-font);
          font-size: 12px;
          letter-spacing: 0.16em;
          text-transform: uppercase;
          color: #2c6f7b;
          font-weight: 700;
        }

        .brim-startup-title {
          margin: 0;
          font-family: var(--brim-headline-font);
          font-size: 35px;
          line-height: 1.02;
          font-weight: 700;
          letter-spacing: -0.015em;
          color: #0d2227;
