        }

        .brim-photo-loader svg {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          display: block;
          pointer-events: none;
          overflow: visible;
        }

        .brim-flow-dots {
          fill: none;
          stroke-linecap: round;
          stroke-linejoin: round;
          mix-blend-mode: screen;
          vector-effect: non-scaling-stroke;
          filter:
            drop-shadow(0 0 4px rgba(181, 240, 255, 0.78))
            drop-shadow(0 0 9px rgba(66, 195, 255, 0.58));
          animation-name: brim-flow-down;
          animation-timing-function: linear;
          animation-iteration-count: infinite;
          will-change: stroke-dashoffset;
        }

        .brim-flow-major {
          stroke: rgba(232, 253, 255, 0.98);
          stroke-width: 7;
          stroke-dasharray: 0.1 31;
          animation-duration: 1.55s;
        }

        .brim-flow-major-soft {
          stroke: rgba(90, 212, 255, 0.58);
          stroke-width: 13;
          stroke-dasharray: 0.1 42;
          animation-duration: 2.05s;
          filter: drop-shadow(0 0 10px rgba(60, 190, 255, 0.42));
        }

        .brim-flow-minor {
          stroke: rgba(207, 245, 255, 0.86);
          stroke-width: 4.4;
          stroke-dasharray: 0.1 35;
          animation-duration: 2.15s;
        }

        .brim-flow-minor-soft {
          stroke: rgba(83, 205, 255, 0.36);
          stroke-width: 8;
          stroke-dasharray: 0.1 48;
          animation-duration: 2.75s;
          filter: drop-shadow(0 0 7px rgba(60, 190, 255, 0.30));
        }

        .brim-flow-fast  { animation-duration: 1.22s; }
        .brim-flow-slow  { animation-duration: 3.10s; }
        .brim-flow-delay-1 { animation-delay: -0.42s; }
        .brim-flow-delay-2 { animation-delay: -0.86s; }
        .brim-flow-delay-3 { animation-delay: -1.31s; }

        @keyframes brim-flow-down {
          from { stroke-dashoffset: 96; }
          to   { stroke-dashoffset: -96; }
        }

        .brim-flow-node {
          fill: rgba(214, 247, 255, 0.08);
          stroke: rgba(229, 252, 255, 0.42);
          stroke-width: 1.8;
          mix-blend-mode: screen;
          transform-origin: center;
          animation: brim-node-pulse 1.85s ease-in-out infinite;
          filter: drop-shadow(0 0 6px rgba(115, 223, 255, 0.38));
        }

        .brim-flow-node.minor {
          stroke-width: 1.3;
          opacity: 0.52;
          animation-delay: -0.75s;
        }

        @keyframes brim-node-pulse {
          0%, 100% { opacity: 0.36; transform: scale(0.96); }
          50% { opacity: 0.75; transform: scale(1.06); }
        }

        .brim-startup-status {
          display: flex;
          align-items: center;
          margin: 0;
          min-height: 44px;
          padding: 10px 13px;
          border-left: 3px solid #2e8eab;
          border-radius: 0 10px 10px 0;
          background: rgba(225, 240, 244, 0.72);
          box-sizing: border-box;
          font-family: Inter, "Segoe UI", Roboto, Arial, Helvetica, sans-serif;
          font-size: 13px;
          line-height: 1.35;
          font-weight: 600;
          color: #1a505b;
        }

        .brim-startup-lower {
          display: grid;
          grid-template-columns: minmax(0, 1fr) auto;
          align-items: center;
          column-gap: 24px;
          min-width: 0;
        }

        .brim-startup-progress {
          min-width: 0;
          align-self: center;
        }

        .brim-startup-branding {
          --brim-doi-width: 120px;
          --brim-blm-width: 129px;
          --brim-brand-clearspace: 55px;
          display: grid;
          grid-template-columns: var(--brim-doi-width) var(--brim-blm-width);
          align-items: center;
          justify-items: center;
          justify-content: center;
          justify-self: end;
          align-self: center;
          gap: var(--brim-brand-clearspace);
          padding: var(--brim-brand-clearspace);
          line-height: 0;
          box-sizing: content-box;
          background: transparent;
          pointer-events: none;
          user-select: none;
          -webkit-user-select: none;
        }

