          }

          .brim-startup-lower {
            grid-template-columns: minmax(0, 1fr);
            row-gap: 0;
          }

          .brim-startup-branding {
            --brim-doi-width: 80px;
            --brim-blm-width: 86px;
            --brim-brand-clearspace: 37px;
            justify-self: center;
          }
        }

        @media (max-width: 480px) {
          .brim-startup-card {
            padding: 22px 20px 18px 20px;
          }

          .brim-startup-branding {
            --brim-doi-width: 55px;
            --brim-blm-width: 59px;
            --brim-brand-clearspace: 26px;
          }
        }

        @media (max-width: 260px) {
          .brim-startup-card {
            padding-left: 14px;
            padding-right: 14px;
          }

          .brim-startup-branding {
            grid-template-columns: 1fr;
          }
        }

        @media (max-height: 900px) and (min-width: 761px) {
          .brim-startup-branding {
            --brim-doi-width: 110px;
            --brim-blm-width: 119px;
            --brim-brand-clearspace: 51px;
          }
        }

        @media (max-height: 720px) and (min-width: 761px) {
          .brim-photo-loader {
            margin-bottom: 12px;
          }

          .brim-startup-branding {
            --brim-doi-width: 85px;
            --brim-blm-width: 91px;
            --brim-brand-clearspace: 39px;
          }
        }
      )---")
    ),
    htmltools::tags$div(
      id = "brim-startup-loading-overlay",
      style = paste0(
        "--brim-topo-background: url('",
        topo_background_uri,
        "');"
      ),
      htmltools::tags$div(
        class = "brim-startup-card",
        htmltools::tags$div(
          class = "brim-startup-heading",
          htmltools::tags$p(class = "brim-startup-kicker", "Loading browser map"),
          htmltools::tags$h1(class = "brim-startup-title", "BRIM"),
          htmltools::tags$p(class = "brim-startup-fullname", "BLM-California Resources Information Mapper"),
          htmltools::tags$p(class = "brim-startup-subtitle", "A hydrology-centered browser map for water-resource screening, live conditions, and resource-review support.")
        ),
        htmltools::tags$div(
          class = "brim-photo-loader",
          style = paste0("background-image:url('", brim_loader_bg_uri, "');"),
          htmltools::HTML(r"---(
            <svg viewBox='0 0 1672 941' role='img' aria-label='BRIM animated loading graphic with downstream flow particles over a landscape' preserveAspectRatio='xMidYMin slice'>
              <defs>
                <!-- All paths are intentionally ordered upstream-to-downstream / top-of-image to bottom-of-image. -->
                <path id='brim-path-reservoir-main' d='M1228 252 C1162 247, 1098 258, 1042 287 C1008 306, 992 329, 985 356' />
                <path id='brim-path-dam-main' d='M985 356 C980 425, 940 500, 868 552 C829 580, 792 586, 760 578' />
                <path id='brim-path-main-lower' d='M760 578 C709 649, 635 769, 532 941' />
                <path id='brim-path-left-trib' d='M412 220 C506 244, 571 286, 593 344 C617 405, 650 460, 701 518 C725 545, 744 564, 760 578' />
                <path id='brim-path-right-upper' d='M1334 258 C1366 285, 1370 319, 1338 360 C1305 397, 1277 415, 1248 423' />
                <path id='brim-path-right-main' d='M1248 423 C1367 453, 1516 492, 1488 533 C1455 578, 1335 610, 1206 641' />
                <path id='brim-path-right-lower' d='M1206 641 C1290 706, 1345 792, 1363 941' />
              </defs>

              <!-- Major flow: reservoir, dam outlet, and mainstem. No filled guide polygons. -->
              <use href='#brim-path-reservoir-main' class='brim-flow-dots brim-flow-major-soft brim-flow-slow'/>
              <use href='#brim-path-reservoir-main' class='brim-flow-dots brim-flow-major brim-flow-slow brim-flow-delay-2'/>
              <use href='#brim-path-dam-main' class='brim-flow-dots brim-flow-major-soft'/>
              <use href='#brim-path-dam-main' class='brim-flow-dots brim-flow-major brim-flow-delay-1'/>
              <use href='#brim-path-main-lower' class='brim-flow-dots brim-flow-major-soft brim-flow-fast'/>
              <use href='#brim-path-main-lower' class='brim-flow-dots brim-flow-major brim-flow-fast brim-flow-delay-2'/>

              <!-- Minor flow: mountain tributary and right-side canal/side-channel branches. -->
              <use href='#brim-path-left-trib' class='brim-flow-dots brim-flow-minor-soft'/>
              <use href='#brim-path-left-trib' class='brim-flow-dots brim-flow-minor brim-flow-delay-2'/>
              <use href='#brim-path-right-upper' class='brim-flow-dots brim-flow-minor-soft'/>
              <use href='#brim-path-right-upper' class='brim-flow-dots brim-flow-minor brim-flow-delay-1'/>
              <use href='#brim-path-right-main' class='brim-flow-dots brim-flow-minor-soft'/>
              <use href='#brim-path-right-main' class='brim-flow-dots brim-flow-minor brim-flow-delay-2'/>
              <use href='#brim-path-right-lower' class='brim-flow-dots brim-flow-minor-soft'/>
              <use href='#brim-path-right-lower' class='brim-flow-dots brim-flow-minor brim-flow-delay-1'/>

              <!-- Subtle existing-node emphasis only. -->
              <circle class='brim-flow-node' cx='985' cy='356' r='13'/>
              <circle class='brim-flow-node' cx='760' cy='578' r='15'/>
              <circle class='brim-flow-node minor' cx='1248' cy='423' r='9'/>
              <circle class='brim-flow-node minor' cx='1206' cy='641' r='11'/>
