        ),
        htmltools::tags$div(
          class = "brim-startup-lower",
          htmltools::tags$div(
            class = "brim-startup-progress",
            htmltools::tags$p(
              id = "brim-startup-loading-status",
              class = "brim-startup-status",
              role = "status",
              `aria-live` = "polite",
              `aria-atomic` = "true",
              "Initializing the BRIM browser map and core services…"
            )
          ),
          htmltools::tags$div(
            class = "brim-startup-branding",
            `aria-hidden` = "true",
            htmltools::tags$img(
              id = "brim-startup-doi-seal",
              class = "brim-startup-brand-mark",
              src = doi_seal_uri,
              alt = "",
              `aria-hidden` = "true",
              draggable = "false"
            ),
            htmltools::tags$img(
              id = "brim-startup-blm-emblem",
              class = "brim-startup-brand-mark",
              src = blm_emblem_uri,
              alt = "",
              `aria-hidden` = "true",
              draggable = "false"
            )
          )
        )
      )
    ),
    htmltools::tags$script(
      htmltools::HTML(r"---(
        (function() {
          var ended = false;
          var statusByStep = {
            shell: 'Initializing the BRIM browser map and core services…',
            layers: 'Preparing cached resource datasets and screening layers…',
            panels: 'Loading live-condition interfaces and resource-review tools…',
            labels: 'Finalizing map annotations, legends, and browser presentation…',
            ready: 'BRIM is ready.'
          };

          function cleanBrand(message) {
            return String(message || '')
              .replace(/PortaTreasure2/g, 'BRIM')
              .replace(/PT2/g, 'BRIM');
          }

          function safeConsole(fn, a, b) {
            try {
              if (window.console && typeof window.console[fn] === 'function') {
                if (b !== undefined) {
                  window.console[fn](a, b);
                } else {
                  window.console[fn](a);
                }
              }
            } catch (e) {}
          }

          safeConsole('time', 'BRIM browser startup');

          function setStatus(message) {
            var status = document.getElementById('brim-startup-loading-status');
            if (status && message) {
              status.textContent = cleanBrand(message);
            }
          }

          window.pt2StartupLoading = {
            mark: function(message, stepName) {
              if (ended) return;
              var cleanMessage = statusByStep[stepName] ||
                cleanBrand(message || 'Preparing the BRIM browser map…');
              setStatus(cleanMessage);
              try {
                if (window.console && typeof window.console.timeLog === 'function') {
                  window.console.timeLog('BRIM browser startup', cleanMessage || stepName || 'startup milestone');
                } else {
                  safeConsole('log', 'BRIM startup: ' + (cleanMessage || stepName || 'startup milestone'));
                }
              } catch (e) {}
            },

            finish: function(message, delayMs) {
              if (ended) return;
              ended = true;
              setStatus(cleanBrand(message || 'BRIM is ready.'));

              var delay = Number(delayMs);
              if (!isFinite(delay)) delay = 650;

              window.setTimeout(function() {
                var overlay = document.getElementById('brim-startup-loading-overlay');
                if (overlay) {
                  overlay.classList.add('brim-startup-loading-hidden');
                  window.setTimeout(function() {
                    if (overlay && overlay.parentNode) {
                      overlay.parentNode.removeChild(overlay);
                    }
                  }, 520);
                }

                try {
                  if (window.console && typeof window.console.timeEnd === 'function') {
                    window.console.timeEnd('BRIM browser startup');
                  }
                } catch (e) {}
              }, delay);
            }
          };

          document.addEventListener('readystatechange', function() {
            if (window.pt2StartupLoading && !ended) {
              window.pt2StartupLoading.mark('Browser document state: ' + document.readyState + '…', 'shell');
            }
          });
        })();
      )---")
    )
  )

  htmlwidgets::prependContent(m, loading_markup)
}

pt_startup_loading_mark <- function(m, message, step = NULL) {
  htmlwidgets::onRender(
    m,
    "
function(el, x, data) {
  if (window.pt2StartupLoading && typeof window.pt2StartupLoading.mark === 'function') {
    window.pt2StartupLoading.mark(data.message, data.step);
  }
}
    ",
    data = list(
      message = pt_startup_loading_brand_message(message),
      step = step
    )
  )
}

pt_finish_startup_loading <- function(m, message = "BRIM is ready.", delay_ms = 800) {
  htmlwidgets::onRender(
    m,
    "
function(el, x, data) {
  function finishStartup() {
    if (window.pt2StartupLoading && typeof window.pt2StartupLoading.finish === 'function') {
      window.pt2StartupLoading.finish(data.message, data.delayMs);
    }
  }

  if (this && typeof this.whenReady === 'function') {
    this.whenReady(function() {
      window.setTimeout(finishStartup, 100);
    });
  } else {
    window.setTimeout(finishStartup, 100);
  }
}
    ",
    data = list(
      message = pt_startup_loading_brand_message(message),
      delayMs = delay_ms
    )
  )
}
